mapper.select:
SELECT SHIFT_DATE,EQP_G,SPECIAL_FLAG,CLN_WAFER_COUNT,CLN_TIME_COUNT,TOTAL_COUNT ,CASE WHEN SUBSTR(EQP_G,1,1) = 'D' THEN ROUND(CLN_WAFER_COUNT*100/TOTAL_COUNT,1) END CLN_WAFER_SCORE ,ROUND(CLN_TIME_COUNT*100/TOTAL_COUNT,1)CLN_TIME_SCORE ,CASE WHEN SUBSTR(EQP_G,1,1) = 'M' THEN 'PVD' WHEN SUBSTR(EQP_G,1,1) = 'D' THEN 'CVD' END AREA ,'TF' MODULE FROM( SELECT SHIFT_DATE,EQP_G,SPECIAL_FLAG,SUM(CLN_WAFER_FLAG)CLN_WAFER_COUNT ,SUM(CLN_TIME_FLAG)CLN_TIME_COUNT ,COUNT(1) TOTAL_COUNT FROM( SELECT C.SHIFT_DATE, C.FAB,C.EQP_G,C.TOOL_NAME,C.CLN_GROUP,C.CLN_RUN_ID,C.CLN_WAFER ,C.CLN_TIME,C.CLN_RECIPE_NAME,C.RECIPENAME ,C.SPECIAL_FLAG,D.CLN_WAFER_TARGET,D.CLN_TIME_MEDIAN ,CASE WHEN C.CLN_WAFER = D.CLN_WAFER_TARGET THEN 1 ELSE 0 END CLN_WAFER_FLAG ,CASE WHEN C.CLN_TIME/D.CLN_TIME_MEDIAN < 1.05 THEN 1 ELSE 0 END CLN_TIME_FLAG FROM( SELECT A.SHIFT_DATE, A.FAB,A.EQP_G,A.TOOL_NAME,A.CLN_GROUP,A.CLN_RUN_ID,A.CLN_WAFER,A.CLN_TIME,A.CLN_RECIPE_NAME,A.RECIPENAME,B.SPECIAL_FLAG ,SUBSTR(A.TOOL_NAME,1,3) TOOL_FLAG FROM( SELECT FAB,SHIFT_DATE, EQP_G,TOOL_NAME,CLN_GROUP,CLN_RUN_ID,CLN_WAFER,CLN_TIME,CLN_RECIPE_NAME,RECIPENAME FROM A1_MFG.TF_CLN_DETAILS WHERE LENGTH(LOT_ID)=10
AND SHIFT_DATE BETWEEN #{startDate,jdbcType=VARCHAR} AND #{endDate,jdbcType=VARCHAR}
AND SHIFT_DATE =TO_CHAR(SYSDATE-10.5/24-1,'YYYYMMDD')
)A LEFT JOIN ( SELECT KEY1 FAB ,KEY2 TOOL_NAME ,KEY3 SPECIAL_FLAG FROM A1_MFG.COMMENT_SUMMARY WHERE FUNCTION_NAME = 'TF_CLN_SPECIAL_FLAG_INFO' )B ON A.FAB = B.FAB AND A.TOOL_NAME = B.TOOL_NAME )C LEFT JOIN A1_MFG.TF_CLN_TARGET D ON C.EQP_G = D.EQP_G AND C.RECIPENAME = D.RECIPENAME AND NVL(C.SPECIAL_FLAG,'NULL') = NVL(D.SPECIAL_FLAG,'NULL') )E GROUP BY EQP_G,SHIFT_DATE,SPECIAL_FLAG ) ORDER BY SHIFT_DATE,DECODE(SUBSTR(EQP_G,1,1),'D',1,2),EQP_G,SPECIAL_FLAG

SELECT SHIFT_DATE,EQP_G,SPECIAL_FLAG,RECIPENAME ,CASE WHEN SUBSTR(EQP_G,1,1) = 'D' THEN CLN_WAFER_TARGET END CLN_WAFER_TARGET,CLN_WAFER_ACT ,CASE WHEN SUBSTR(EQP_G,1,1) = 'D' THEN ROUND(CLN_WAFER_COUNT*100/TOTAL_COUNT,1) END CLN_WAFER_RATIO ,CLN_TIME_ACT ,CLN_TIME_TARGET ,ROUND(CLN_TIME_COUNT*100/TOTAL_COUNT,1)CLN_TIME_RATIO ,CASE WHEN SUBSTR(EQP_G,1,1) = 'M' THEN 'PVD' WHEN SUBSTR(EQP_G,1,1) = 'D' THEN 'CVD' END AREA ,'TF' MODULE ,TOTAL_COUNT FROM( SELECT SHIFT_DATE,EQP_G,SPECIAL_FLAG,RECIPENAME,SUM(CLN_WAFER_FLAG)CLN_WAFER_COUNT ,COUNT(1) TOTAL_COUNT ,MAX(CLN_WAFER)CLN_WAFER_ACT,MAX(E.CLN_WAFER_TARGET )CLN_WAFER_TARGET ,MEDIAN(CLN_TIME) CLN_TIME_ACT,MAX(CLN_TIME_MEDIAN)CLN_TIME_TARGET ,SUM(CLN_TIME_FLAG)CLN_TIME_COUNT FROM( SELECT C.SHIFT_DATE, C.FAB,C.EQP_G,C.TOOL_NAME,C.CLN_GROUP,C.CLN_RUN_ID,C.CLN_WAFER ,C.CLN_TIME,C.CLN_RECIPE_NAME,C.RECIPENAME ,C.SPECIAL_FLAG,D.CLN_WAFER_TARGET,D.CLN_TIME_MEDIAN ,CASE WHEN C.CLN_WAFER = D.CLN_WAFER_TARGET THEN 1 ELSE 0 END CLN_WAFER_FLAG ,CASE WHEN C.CLN_TIME / D.CLN_TIME_MEDIAN < 1.05 THEN 1 ELSE 0 END CLN_TIME_FLAG FROM( SELECT A.SHIFT_DATE, A.FAB,A.EQP_G,A.TOOL_NAME,A.CLN_GROUP,A.CLN_RUN_ID,A.CLN_WAFER,A.CLN_TIME,A.CLN_RECIPE_NAME,A.RECIPENAME,B.SPECIAL_FLAG ,SUBSTR(A.TOOL_NAME,1,3) TOOL_FLAG FROM( SELECT FAB,SHIFT_DATE, EQP_G,TOOL_NAME,CLN_GROUP,CLN_RUN_ID,CLN_WAFER,CLN_TIME,CLN_RECIPE_NAME,RECIPENAME FROM A1_MFG.TF_CLN_DETAILS WHERE SHIFT_DATE = #{date,jdbcType=VARCHAR} AND LENGTH(LOT_ID)=10 AND EQP_G = #{eqpg,jdbcType=VARCHAR} )A LEFT JOIN ( SELECT KEY1 FAB ,KEY2 TOOL_NAME ,KEY3 SPECIAL_FLAG FROM A1_MFG.COMMENT_SUMMARY WHERE FUNCTION_NAME = 'TF_CLN_SPECIAL_FLAG_INFO' )B ON A.FAB = B.FAB AND A.TOOL_NAME = B.TOOL_NAME WHERE 1=1
AND B.SPECIAL_FLAG = #{specialFlag,jdbcType=VARCHAR}
AND B.SPECIAL_FLAG IS NULL
)C LEFT JOIN A1_MFG.TF_CLN_TARGET D ON C.EQP_G = D.EQP_G AND C.RECIPENAME = D.RECIPENAME AND NVL(C.SPECIAL_FLAG,'NULL') = NVL(D.SPECIAL_FLAG,'NULL') )E GROUP BY EQP_G,SHIFT_DATE,SPECIAL_FLAG,RECIPENAME )

SELECT SHIFT_DATE,EQP_G,SPECIAL_FLAG,RECIPENAME ,CASE WHEN SUBSTR(EQP_G,1,1) = 'D' THEN CLN_WAFER_TARGET END CLN_WAFER_TARGET ,CLN_WAFER_ACT ,TOOL_NAME ,CASE WHEN SUBSTR(EQP_G,1,1) = 'D' THEN ROUND(CLN_WAFER_COUNT*100/TOTAL_COUNT,1) END CLN_WAFER_RATIO ,CLN_TIME_ACT ,CLN_TIME_TARGET ,ROUND(CLN_TIME_COUNT*100/TOTAL_COUNT,1)CLN_TIME_RATIO ,CASE WHEN SUBSTR(EQP_G,1,1) = 'M' THEN 'PVD' WHEN SUBSTR(EQP_G,1,1) = 'D' THEN 'CVD' END AREA ,'TF' MODULE ,TOTAL_COUNT FROM( SELECT SHIFT_DATE,EQP_G,SPECIAL_FLAG,RECIPENAME,TOOL_NAME ,SUM(CLN_WAFER_FLAG)CLN_WAFER_COUNT ,COUNT(1) TOTAL_COUNT ,MAX(CLN_WAFER)CLN_WAFER_ACT,MAX(E.CLN_WAFER_TARGET )CLN_WAFER_TARGET ,MEDIAN(CLN_TIME) CLN_TIME_ACT,MAX(CLN_TIME_MEDIAN)CLN_TIME_TARGET ,SUM(CLN_TIME_FLAG)CLN_TIME_COUNT FROM( SELECT C.SHIFT_DATE, C.FAB,C.EQP_G,C.TOOL_NAME,C.CLN_GROUP,C.CLN_RUN_ID,C.CLN_WAFER ,C.CLN_TIME,C.CLN_RECIPE_NAME,C.RECIPENAME ,C.SPECIAL_FLAG,D.CLN_WAFER_TARGET,D.CLN_TIME_MEDIAN ,CASE WHEN C.CLN_WAFER = D.CLN_WAFER_TARGET THEN 1 ELSE 0 END CLN_WAFER_FLAG ,CASE WHEN C.CLN_TIME / D.CLN_TIME_MEDIAN < 1.05 THEN 1 ELSE 0 END CLN_TIME_FLAG FROM( SELECT A.SHIFT_DATE, A.FAB,A.EQP_G,A.TOOL_NAME,A.CLN_GROUP,A.CLN_RUN_ID,A.CLN_WAFER,A.CLN_TIME,A.CLN_RECIPE_NAME,A.RECIPENAME,B.SPECIAL_FLAG ,SUBSTR(A.TOOL_NAME,1,3) TOOL_FLAG FROM( SELECT FAB,SHIFT_DATE, EQP_G,TOOL_NAME,CLN_GROUP,CLN_RUN_ID,CLN_WAFER,CLN_TIME,CLN_RECIPE_NAME,RECIPENAME FROM A1_MFG.TF_CLN_DETAILS WHERE SHIFT_DATE = #{date,jdbcType=VARCHAR} AND LENGTH(LOT_ID)=10 AND EQP_G = #{eqpg,jdbcType=VARCHAR} AND RECIPENAME = #{recipe,jdbcType=VARCHAR} )A LEFT JOIN ( SELECT KEY1 FAB ,KEY2 TOOL_NAME ,KEY3 SPECIAL_FLAG FROM A1_MFG.COMMENT_SUMMARY WHERE FUNCTION_NAME = 'TF_CLN_SPECIAL_FLAG_INFO' )B ON A.FAB = B.FAB AND A.TOOL_NAME = B.TOOL_NAME WHERE 1=1
AND B.SPECIAL_FLAG = #{specialFlag,jdbcType=VARCHAR}
AND B.SPECIAL_FLAG IS NULL
)C LEFT JOIN A1_MFG.TF_CLN_TARGET D ON C.EQP_G = D.EQP_G AND C.RECIPENAME = D.RECIPENAME AND NVL(C.SPECIAL_FLAG,'NULL') = NVL(D.SPECIAL_FLAG,'NULL') )E GROUP BY EQP_G,SHIFT_DATE,SPECIAL_FLAG,RECIPENAME,TOOL_NAME )

SELECT C.START_TIME,C.CLN_WAFER CLN_WAFER_CLN ,C.CLN_TIME ,CASE WHEN SUBSTR(C.EQP_G,1,1) = 'D' THEN D.CLN_WAFER_TARGET END CLN_WAFER_TARGET ,D.CLN_TIME_MEDIAN FROM( SELECT A.SHIFT_DATE,A.START_TIME, A.FAB,A.EQP_G,A.TOOL_NAME,A.CLN_GROUP,A.CLN_RUN_ID,A.CLN_WAFER,A.CLN_TIME,A.CLN_RECIPE_NAME,A.RECIPENAME,B.SPECIAL_FLAG ,SUBSTR(A.TOOL_NAME,1,3) TOOL_FLAG FROM( SELECT FAB,SHIFT_DATE, EQP_G,TOOL_NAME,CLN_GROUP,CLN_RUN_ID,CLN_WAFER,CLN_TIME,CLN_RECIPE_NAME,RECIPENAME ,START_TIME FROM A1_MFG.TF_CLN_DETAILS WHERE SHIFT_DATE =#{date,jdbcType=VARCHAR} AND LENGTH(LOT_ID)=10 AND EQP_G = #{eqpg,jdbcType=VARCHAR} AND RECIPENAME = #{recipe,jdbcType=VARCHAR}
AND INSTR(','||#{toolName,jdbcType=VARCHAR}||',' ,TOOL_NAME) >0
)A LEFT JOIN ( SELECT KEY1 FAB ,KEY2 TOOL_NAME ,KEY3 SPECIAL_FLAG FROM A1_MFG.COMMENT_SUMMARY WHERE FUNCTION_NAME = 'TF_CLN_SPECIAL_FLAG_INFO' )B ON A.FAB = B.FAB AND A.TOOL_NAME = B.TOOL_NAME WHERE 1=1
AND B.SPECIAL_FLAG = #{specialFlag,jdbcType=VARCHAR}
AND B.SPECIAL_FLAG IS NULL
)C LEFT JOIN A1_MFG.TF_CLN_TARGET D ON C.EQP_G = D.EQP_G AND C.RECIPENAME = D.RECIPENAME AND NVL(C.SPECIAL_FLAG,'NULL') = NVL(D.SPECIAL_FLAG,'NULL') ORDER BY C.START_TIME ASC

mapper.insert:
MERGE INTO A1_MFG.COMMENT_SUMMARY A USING( SELECT 'TF_CLN_SPECIAL_FLAG_INFO' FUNCTION_NAME, B.FAB,A.TOOL_NAME,A.SPECIAL_FLAG,#{UPDATE_USER} UPDATE_USER FROM(
SELECT #{item.TOOL_NAME} TOOL_NAME,#{item.SPECIAL_FLAG} SPECIAL_FLAG FROM DUAL
)A JOIN ( SELECT FAB ,REPLACE(EQP_ID,'.','_')TOOL_NAME FROM A3MFGYW1.PWEB_EQP_ID_USE_STD WHERE SHIFT_DATE = TO_CHAR(SYSDATE-7.5/24-1,'YYYYMMDD') )B ON A.TOOL_NAME = B.TOOL_NAME )B ON (A.KEY1 = B.FAB AND A.KEY2 = B.TOOL_NAME AND A.FUNCTION_NAME = B.FUNCTION_NAME) WHEN MATCHED THEN UPDATE SET A.KEY3 = B.SPECIAL_FLAG,A.UPDATE_TIME = SYSDATE,A.UPDATE_USER = B.UPDATE_USER WHEN NOT MATCHED THEN INSERT (FUNCTION_NAME ,KEY1,KEY2,KEY3,UPDATE_USER,UPDATE_TIME)VALUES(B.FUNCTION_NAME ,B.FAB,B.TOOL_NAME,B.SPECIAL_FLAG,B.UPDATE_USER,SYSDATE)

mapper.delete:
DELETE FROM A1_MFG.COMMENT_SUMMARY
WHERE FUNCTION_NAME = 'TF_CLN_FILTER_INFO'
AND KEY1 = #{EQP_G}
AND KEY2 = #{TOOL_NAME}
AND KEY3 = #{RECIPENAME}
